// strings.js — port of android/feature/progress/src/main/res/values/strings.xml (generated 1:1).
// R.string.x is the format string ('%%' already unescaped to '%'); format with stringResource / pluralStringResource.

const fmt = (f, args) => f.replace(/%(?:(\d+)\$)?([sd])/g, (_, pos, conv) => {
  const v = args[pos ? Number(pos) - 1 : 0];
  return conv === 'd' ? String(Math.trunc(Number(v))) : String(v ?? 'null');
});

