/** stringResource(R.string.x, ...args) */
export const stringResource = (f, ...args) => (args.length ? fmt(f, args) : f);
/** pluralStringResource(R.plurals.x, quantity, ...args) — English rules: "one" for 1, "other" otherwise. */
export const pluralStringResource = (pl, quantity, ...args) => fmt(quantity === 1 && pl.one != null ? pl.one : pl.other, args);
